function openSearch(){$('#searchDialog').showModal();$('#globalQuery').focus();paintGlobalSearch();}
function paintGlobalSearch(){const q=$('#globalQuery').value.toLowerCase();$('#globalResults').innerHTML=D.filter(d=>[d.name,d.type,d.summary].join(' ').toLowerCase().includes(q)).map(d=>`<a href="${href(d)}"><strong>${esc(d.name)}</strong><span>${esc(d.type)}${d.demo?' · Fictional demo':''}</span></a>`).join('')||'<p>No matching components.</p>';$$('#globalResults a').forEach(a=>a.onclick=()=>$('#searchDialog').close());}
function openStack(){$('#stackBody').innerHTML=stack.length?stack.map(id=>{const d=D.find(d=>d.id===id);return d?`<div class="stack-row"><a href="${href(d)}">${esc(d.name)}</a><button data-remove-stack="${id}" aria-label="Remove ${esc(d.name)}">×</button></div>`:'';}).join('')+`<button id="exportStack" class="primary">Export stack manifest</button><p class="muted">Exports resource references. Nothing is installed.</p>`:'<div class="empty"><h3>Your stack is empty</h3><p>Use the + button on a component to build your collection.</p></div>';$$('[data-remove-stack]').forEach(b=>b.onclick=()=>{stack=stack.filter(id=>id!==b.dataset.removeStack);saveStack();openStack();});$('#exportStack')&&($('#exportStack').onclick=()=>download(B.id+'-stack.json',JSON.stringify({brand:B.name,resources:stack,install:false},null,2)));if(!$('#stackDialog').open)$('#stackDialog').showModal();$$('#stackBody a').forEach(a=>a.onclick=()=>$('#stackDialog').close());}
function saveStack(){try{localStorage.setItem(B.id+'-stack',JSON.stringify(stack));}catch{}if($('#stackCount'))$('#stackCount').textContent=stack.length;}
const beforeCard3=card;
card=function(d){if(V!==5)return beforeCard3(d);return `<article class="template-card"><span class="component-icon">${d.type==='Skill'?'◇':d.type==='MCP Server'?'♧':d.type==='Repository'?'⌘':'▧'}</span><div><h3><a href="${href(d)}">${esc(d.name)}</a></h3><p>${esc(d.summary)}</p><div class="component-tags">${badge(d.category)}${badge(d.demo?'Demo':d.license)}</div></div><div class="component-actions"><button data-save="${d.id}" aria-label="Save ${esc(d.name)}">${state.saved.includes(d.id)?'★':'☆'}</button><button data-stack="${d.id}" aria-label="Add ${esc(d.name)} to stack">+</button></div></article>`;};
const beforeSearch3=searchView;
searchView=function(kind='discover',items=pool(),title){let html=beforeSearch3(kind,items,title);if(V===5){const cats=[...new Set(items.map(d=>d.category))];html=`${kind==='discover'?`<section class="template-hero"><h1 class="ascii-brand">${B.id==='lawyer'?'SOMEONE.LAWYER':'AI COMPANY<br>MARKET'}</h1><p>Ready-to-use components for your ${B.id==='lawyer'?'legal technology':'AI company'} projects</p><div class="template-stats"><a href="#/products"><strong>${D.filter(d=>!d.demo).length}</strong>Source samples</a><a href="#/categories"><strong>${cats.length}</strong>Categories</a><a href="#/saved"><strong>${state.saved.length}</strong>Saved components</a></div></section>`:`<section class="page-title"><h1>${esc(title||kind.replaceAll('-',' '))}</h1><p>Explore ${esc((title||kind).toLowerCase())} for your ${B.id==='lawyer'?'legal technology':'AI company'} stack.</p></section>`}<div class="template-directory"><div><form class="searchbox" id="searchForm"><input id="search" type="search" aria-label="Search resources" placeholder="Search components…" value="${esc(state.query)}"><button class="primary">Search</button></form><div class="template-toolbar"><select id="categorySelect" aria-label="Category"><option value="All">All categories</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><button id="filterToggle" aria-controls="filters" aria-expanded="false">☷ Filters</button><button data-display="grid" aria-label="Grid view" aria-pressed="true">▦</button><button data-display="list" aria-label="List view" aria-pressed="false">☰</button><select id="sort" aria-label="Sort resources"><option value="editorial">Directory order</option><option value="az">Name</option><option value="type">Type</option></select></div><aside class="filters" id="filters"><fieldset><legend>Component type</legend>${[...new Set(items.map(d=>d.type))].map(t=>`<label><input type="checkbox" data-type="${t}">${t}</label>`).join('')}</fieldset><label><input type="checkbox" id="savedOnly">Saved only</label><button id="reset">Reset</button></aside><div class="results-head"><span id="count"></span></div><div class="cards" id="cards"></div></div><aside class="template-jobs"><h3>Resources <span>↗</span></h3>${[['docs','Documentation','Learn the component workflow'],['how-to-install','Installation guide','From source to local setup'],['provenance-and-licences','Source & licences','Know who made it'],['jobs','Jobs','No live vacancies in this preview']].map(([r,t,p])=>miniLink(r,t,p)).join('')}</aside></div>`;return html;}
 if(kind==='discover'&&V===1){html=html.replace('<div class="catalogue">','<div class="catalogue">');}
 if(V===2)html=html.replace('</form>',`<div class="inline-selects"><select id="sourceFilter" aria-label="Source"><option value="all">All sources</option><option value="source">Source linked</option><option value="demo">Fictional demo</option></select><select id="typeFilter" aria-label="Resource type"><option value="all">All types</option>${[...new Set(items.map(d=>d.type))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div></form>`);
 if(kind==='discover'&&V===3)html=html.replace('<div class="categories">',`<section class="publishers"><h2>Source publishers</h2><div>${[...new Set(pool().map(d=>d.owner))].map(owner=>`<a href="#/official">${ico('⌘')}${esc(owner)}</a>`).join('')}</div></section><div class="categories">`);
 if(kind==='discover'&&V===4)html=html.replace('LEGAL TECHNOLOGY / INDEX','Find legal technology,<br>skills, and MCP servers').replace('AI COMPANY / INDEX','Find the best agents,<br>skills, and MCP servers');
 return html;};
const beforeWireSearch3=wireSearch;
wireSearch=function(items){beforeWireSearch3(items);if($('#categorySelect'))$('#categorySelect').onchange=e=>{state.category=e.target.value;paintCards();};if($('#sourceFilter'))$('#sourceFilter').onchange=e=>{currentItems=items.filter(d=>e.target.value==='all'||(e.target.value==='source'?!d.demo:d.demo));paintCards();};if($('#typeFilter'))$('#typeFilter').onchange=e=>{state.types=e.target.value==='all'?[]:[e.target.value];paintCards();};$$('[data-display]').forEach(b=>b.onclick=()=>{$('#cards').classList.toggle('list-display',b.dataset.display==='list');$$('[data-display]').forEach(x=>x.setAttribute('aria-pressed',x===b));});};
const beforeWireCards3=wireCards;
wireCards=function(){beforeWireCards3();$$('[data-stack]').forEach(b=>b.onclick=()=>{if(!stack.includes(b.dataset.stack))stack.push(b.dataset.stack);saveStack();b.textContent='✓';toast('Added to your stack.');});};
function resourceFiles(d){const main=d.type==='Skill'?'SKILL.md':d.type==='MCP Server'?'resource.json':'README.md';const description=`# ${d.name}\n\n${d.description}\n\n## Capabilities\n\n${d.capabilities.map(c=>'- '+c).join('\n')}\n\n## Setup\n\n${d.demo?'Fictional design example. No published package.':'Read the original documentation: '+(d.docs||d.source)}\n\n## Permissions\n\n${d.risk||'Review the source documentation.'}\n\n## Source and licence\n\nMaintainer: ${d.owner}\nLicence: ${d.license}\nSource: ${d.source||'Fictional demo'}\n\nThis is directory-authored documentation, not a copy of upstream source code.`;return {[main]:main.endsWith('.json')?JSON.stringify({name:d.name,type:d.type,source:d.source,license:d.license,runtime:d.runtime,permissions:d.risk,execution_enabled:false},null,2):description,'README.md':description,'manifest.json':JSON.stringify({id:d.id,name:d.name,owner:d.owner,source:d.source,license:d.license,review:'metadata only',demo:d.demo},null,2),'LICENSE-NOTE.txt':`${d.license}\n\nThe original resource remains owned by ${d.owner}.\n${d.licenseUrl||'No licence evidence for this fictional demonstration.'}\n\nThis viewer contains directory-authored records. Consult the primary source for the complete licence.`};}
function setupCommand(d){if(d.demo)return '# Preview only — '+d.id+' is a fictional component';if(d.id==='github-mcp')return 'claude mcp add --transport http github https://api.githubcopilot.com/mcp/';return 'git clone '+d.source.replace(/\/$/,'')+'.git';}
function installPanel(d){return `<section class="install-panel"><div class="install-label">${technical(d)?'Install / source command':'Get the source'}<button data-copy-command="${d.id}">Copy</button></div>${d.type==='Skill'?'<div class="install-tabs"><button class="active" data-scope="project">Project</button><button data-scope="global">Global</button><button data-scope="once">Try once</button></div>':''}${V===2?'<div class="client-tabs"><button class="active" data-client="claude">Claude Code</button><button data-client="codex">Codex</button></div>':''}<pre class="install-command">${esc(setupCommand(d))}</pre><small class="install-note">${d.demo?'Fictional example · no executable package':d.id==='github-mcp'?'Source command · authentication required · not executed':'Downloads source code only; follow the maintainer’s setup guide.'}</small>${external(d.docs||d.source,'Official setup guide')}</section>`;}
function terminal(d){return `<section class="terminal" aria-label="Installation animation"><div class="terminal-title"><span class="traffic"><i></i><i></i><i></i></span><span>${B.id==='lawyer'?'someone':'ai-company'} — ${esc(d.id)}</span><button id="replayTerminal" aria-label="Replay terminal animation">↻ Replay</button><button id="pauseTerminal" aria-label="Pause terminal animation">Ⅱ</button></div><div class="terminal-body" id="terminalBody"></div><div class="terminal-status"><span>~/projects/${B.id==='lawyer'?'legal-stack':'ai-company'}</span><span id="terminalState">Illustrative installation preview</span></div></section>`;}
function editor(d){const files=resourceFiles(d),first=Object.keys(files)[0];return `<section class="code-explorer" data-resource="${d.id}"><div class="explorer-toolbar"><h2>Content</h2><div class="editor-tabs" role="tablist" aria-label="Content format"><button role="tab" aria-selected="true" data-editor="code">Code</button><button role="tab" aria-selected="false" data-editor="preview">Preview</button><button role="tab" aria-selected="false" data-editor="slides">Slides</button></div><button id="searchCode">⌕ Search</button><button id="copyCode">Copy</button><button id="toggleFiles" aria-expanded="true">Files</button><button id="expandCode" aria-label="Expand code viewer">⛶</button></div><div id="codeSearchBox" hidden><input type="search" id="codeQuery" aria-label="Find in file" placeholder="Find in file…"><span id="codeMatches"></span><button id="nextMatch">Next ↓</button></div><div class="explorer-body"><nav class="file-tree" aria-label="Resource files"><small>DIRECTORY FILES</small><strong>⌄ ${esc(d.id)}</strong>${Object.keys(files).map(f=>`<button data-file="${f}" class="${f===first?'active':''}">▧ ${f}</button>`).join('')}<p>Directory-authored records. Original source linked above.</p></nav><div class="code-area"><div class="file-tab" id="fileTab">${first}<span>Read only</span></div><div id="codeContent"></div></div><nav class="document-outline" aria-label="On this page"><small>ON THIS PAGE</small>${['Overview','Capabilities','Setup','Permissions','Source and licence'].map((t,i)=>`<button data-outline="${i}">${t}</button>`).join('')}</nav></div><div class="editor-status"><span id="lineCount"></span><span>UTF-8 · ${esc(d.type)} · local preview</span></div></section>`;}
function resourceHeader(d){return `<div class="resource-heading"><span class="component-icon large">${esc(d.mark)}</span><div><h1>${esc(d.name)}</h1><div class="badges">${badge(d.type)}${badge(d.category)}${badge(d.demo?'Fictional demo':d.license)}</div></div></div><p class="resource-summary">${esc(d.summary)}</p><div class="resource-owner">by ${esc(d.owner)} · ${esc(d.status)}</div>`;}
function readme(d){return `<section class="readme"><h2>${V===4?'README.md':'Overview'}</h2><p>${esc(d.description)}</p><h3>Key features</h3><ul>${d.capabilities.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Use cases</h3><p>${B.id==='lawyer'?'Build source-aware research and document workflows for legal teams.':'Connect reusable capabilities to the workflows of an AI company.'}</p><h3>Technical requirements</h3><table class="metadata">${[['Runtime',d.runtime||'See original documentation'],['Compatibility',d.compatibility],['Permissions',d.risk]].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v||'Not assessed')}</td></tr>`).join('')}</table></section>`;}
function detailAside(d){return `<aside class="resource-aside">${V===3?installPanel(d):''}<section class="metrics-panel">${[['Maintainer',d.owner],['Licence',d.license],['Type',d.type],['Source check',d.demo?'Demo':'27 Sep 2026'],['Security','Not audited']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><h3>Categories</h3>${link('category/'+encodeURIComponent(d.category),esc(d.category))}${external(d.source,'View on GitHub','source-button')}<hr><div class="community-actions"><button data-save="${d.id}" aria-label="Save ${esc(d.name)}">☆ Save</button><button data-compare="${d.id}">Compare +</button></div><h3>Comments</h3><p>No published comments.</p>${link('report/'+d.id,'Suggest a correction →')}</aside>`;}
detail=function(d){let hero=resourceHeader(d),breadcrumb=`<div class="breadcrumb">${link('discover','Home')} › ${link(technical(d)?'technical':'products',esc(d.type))} › ${esc(d.name)}</div>`,warning=d.status==='Deprecated'||d.status==='Maintenance mode'?`<div class="notice"><strong>${esc(d.status)}</strong> ${esc(d.maintenanceNote||'Review maintenance status before choosing this dependency.')}</div>`:'';
 if(V===5)return breadcrumb+`<article class="template-detail"><div class="component-hero"><div><section class="component-identity">${hero}</section>${installPanel(d)}<div class="meta-buttons"><button data-meta="description">Description</button><button data-meta="license">License</button><button data-meta="source">Source</button><button data-stack="${d.id}">+ Add to stack</button></div></div>${terminal(d)}</div>${warning}${editor(d)}</article>`;
 if(V===3)return breadcrumb+`<header class="market-detail-hero">${hero}</header>${warning}<div class="resource-layout"><article><div class="resource-tabs" role="tablist" aria-label="Resource details"><button data-resource-tab="about" role="tab" aria-selected="true">About</button><button data-resource-tab="code" role="tab" aria-selected="false">${d.type==='Skill'?'SKILL.md':d.type==='Repository'?'Repository':'Source files'}</button><button data-resource-tab="faq" role="tab" aria-selected="false">FAQ</button></div><div data-resource-pane="about">${readme(d)}</div><div data-resource-pane="code" hidden>${editor(d)}</div><div data-resource-pane="faq" hidden>${resourceFAQ(d)}</div></article>${detailAside(d)}</div>${related3(d)}`;
 return breadcrumb+`<div class="resource-layout"><article>${hero}${warning}${installPanel(d)}${V===1&&d.type==='Repository'?`<section class="repo-summary"><h2>${esc(d.owner)} / ${esc(d.name)}</h2><p>${esc(d.description)}</p></section>`:''}${d.type==='Skill'||d.type==='Repository'?editor(d):readme(d)}${d.type==='MCP Server'?`<section class="tools-accordion"><h2>Tools & capabilities</h2>${d.capabilities.map(c=>`<details><summary>${esc(c)} <span>+</span></summary><p>${esc(d.risk||'See original tool documentation for parameters and permissions.')}</p>${external(d.docs||d.source,'Read tool documentation')}</details>`).join('')}</section>${V===2?editor(d):''}`:''}</article>${detailAside(d)}</div>${related3(d)}`;};
function related3(d){return `<section class="related"><div class="section-heading"><h2>Related ${d.type==='Skill'?'skills':'resources'}</h2>${link('discover','View all →')}</div><div class="cards">${pool().filter(x=>x.id!==d.id).slice(0,3).map(card).join('')}</div></section>`;}
function resourceFAQ(d){return `<section class="faq">${[['How do I use '+d.name+'?','Review the linked source and setup guide for the current supported installation method.'],['Who maintains this resource?',d.owner],['Which licence applies?',d.license+'. Read the original licence evidence before reuse.'],['Has this resource been installed here?','No. This directory provides resource information and visual installation previews.']].map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section>`;}
let terminalCancel=0,terminalPaused=false;
function animateTerminal(d){const token=++terminalCancel;terminalPaused=false;const body=$('#terminalBody');if(!body)return;body.innerHTML='';$('#terminalState').textContent='Illustrative installation preview';$('#pauseTerminal').textContent='Ⅱ';const lines=[['$ '+setupCommand(d),'default'],['Preparing '+d.type.toLowerCase()+': '+d.name,'blue'],['⠋ Resolving source and component files…','gray'],['✓ Source reference loaded','green'],['✓ Configuration prepared for review','green'],['~/projects/'+(B.id==='lawyer'?'legal-stack':'ai-company'),'cyan'],['','gray'],['> Open '+d.name,'orange'],['⏺ '+d.capabilities[0],'magenta'],['✓ Preview complete. No software was installed.','green']];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let li=0,ci=0,node;const tick=()=>{if(token!==terminalCancel||!body.isConnected)return;if(terminalPaused){setTimeout(tick,120);return;}if(li>=lines.length){$('#terminalState').textContent='Preview complete · Replay available';return;}if(!node){node=document.createElement('div');node.className='tone-'+lines[li][1];body.append(node);}const text=lines[li][0];if(reduced){node.textContent=text;ci=text.length;}else{ci=Math.min(ci+(li===0||li===7?1:6),text.length);node.textContent=text.slice(0,ci)+(ci<text.length?'▋':'');}body.scrollTop=body.scrollHeight;if(ci===text.length){li++;ci=0;node=null;setTimeout(tick,reduced?0:190);}else setTimeout(tick,38);};tick();}
function paintEditor(d,mode='code',file){const el=$('.code-explorer');if(!el)return;const files=resourceFiles(d);el.dataset.mode=mode;el.dataset.file=file||el.dataset.file||Object.keys(files)[0];const text=files[el.dataset.file];$('#fileTab').innerHTML=esc(el.dataset.file)+'<span>Read only</span>';$('#lineCount').textContent=text.split('\n').length+' lines';$$('button[data-file]').forEach(b=>b.classList.toggle('active',b.dataset.file===el.dataset.file));$$('[data-editor]').forEach(b=>b.setAttribute('aria-selected',b.dataset.editor===mode));if(mode==='code')$('#codeContent').innerHTML=`<div class="source-lines">${text.split('\n').map((line,i)=>`<div class="source-line-row"><span class="line-number">${i+1}</span><code class="${line.startsWith('#')?'syntax-heading':/^[\s]*[\"\w-]+[\":]/.test(line)?'syntax-key':''}">${esc(line)||' '}</code></div>`).join('')}</div>`;else if(mode==='preview')$('#codeContent').innerHTML=`<article class="rendered-doc">${el.dataset.file.endsWith('.json')||el.dataset.file.endsWith('.txt')?`<pre>${esc(text)}</pre>`:text.split('\n').map(line=>line.startsWith('# ')?`<h2>${esc(line.slice(2))}</h2>`:line.startsWith('## ')?`<h3>${esc(line.slice(3))}</h3>`:line.startsWith('- ')?`<p>• ${esc(line.slice(2))}</p>`:line?`<p>${esc(line)}</p>`:'').join('')}</article>`;else{el.dataset.slide='0';$('#codeContent').innerHTML=`<section class="slide-view"><small>COMPONENT OVERVIEW</small><h2 id="slideTitle">${esc(d.name)}</h2><p id="slideText">${esc(d.description)}</p><div><button id="prevSlide">← Previous</button><span id="slideIndex">1 / 4</span><button id="nextSlide">Next →</button></div></section>`;const slides=[[d.name,d.description],['Capabilities',d.capabilities.join(' · ')],['Permissions',d.risk||'See original documentation'],['Source & licence',d.owner+' · '+d.license]];const step=delta=>{let n=(+el.dataset.slide+delta+4)%4;el.dataset.slide=n;$('#slideTitle').textContent=slides[n][0];$('#slideText').textContent=slides[n][1];$('#slideIndex').textContent=(n+1)+' / 4';};$('#prevSlide').onclick=()=>step(-1);$('#nextSlide').onclick=()=>step(1);} }
function wireResource(d){if(!d)return;$$('[data-copy-command]').forEach(b=>b.onclick=()=>copyText($('.install-command').textContent,b));$$('[data-client]').forEach(b=>b.onclick=()=>{$$('[data-client]').forEach(x=>x.classList.toggle('active',x===b));$('.install-command').textContent=b.dataset.client==='codex'&&d.id==='github-mcp'?'codex mcp add github --url https://api.githubcopilot.com/mcp/':setupCommand(d);});$$('[data-scope]').forEach(b=>b.onclick=()=>{$$('[data-scope]').forEach(x=>x.classList.toggle('active',x===b));$('.install-note').textContent=d.demo?'Fictional '+b.textContent.toLowerCase()+' installation preview. No package is published.':'Scope: '+b.textContent+'. Check supported flags in the original setup guide.';});if($('.code-explorer')){paintEditor(d);$$('[data-editor]').forEach(b=>b.onclick=()=>paintEditor(d,b.dataset.editor));$$('button[data-file]').forEach(b=>b.onclick=()=>paintEditor(d,$('.code-explorer').dataset.mode,b.dataset.file));$('#copyCode').onclick=e=>copyText(resourceFiles(d)[$('.code-explorer').dataset.file],e.currentTarget);$('#toggleFiles').onclick=e=>{const hidden=$('.file-tree').classList.toggle('hidden');$('.code-explorer').classList.toggle('files-open',!hidden);e.currentTarget.setAttribute('aria-expanded',!hidden);};$('#expandCode').onclick=()=>$('.code-explorer').classList.toggle('expanded');$('#searchCode').onclick=()=>{$('#codeSearchBox').hidden=!$('#codeSearchBox').hidden;if(!$('#codeSearchBox').hidden)$('#codeQuery').focus();};let matchIndex=0;$('#codeQuery').oninput=()=>{paintEditor(d,'code');const q=$('#codeQuery').value.toLowerCase();let matches=0;$$('.source-line-row').forEach(row=>{const hit=q&&row.querySelector('code').textContent.toLowerCase().includes(q);row.classList.toggle('code-hit',!!hit);if(hit)matches++;});$('#codeMatches').textContent=matches+' matching lines';matchIndex=0;};$('#nextMatch').onclick=()=>{const hits=$$('.code-hit');if(hits.length)hits[matchIndex++%hits.length].scrollIntoView({block:'center',behavior:'smooth'});};$$('[data-outline]').forEach(b=>b.onclick=()=>{paintEditor(d,'preview');const hs=$$('#codeContent h2,#codeContent h3');hs[Math.min(+b.dataset.outline,hs.length-1)]?.scrollIntoView({block:'center',behavior:'smooth'});});}$$('[data-resource-tab]').forEach(b=>b.onclick=()=>{$$('[data-resource-tab]').forEach(x=>x.setAttribute('aria-selected',x===b));$$('[data-resource-pane]').forEach(x=>x.hidden=x.dataset.resourcePane!==b.dataset.resourceTab);});$$('[data-meta]').forEach(b=>b.onclick=()=>{$('#metaTitle').textContent=b.textContent;$('#metaBody').textContent=d[b.dataset.meta]||d.description;$('#metaDialog').showModal();});if($('#terminalBody')){animateTerminal(d);$('#replayTerminal').onclick=()=>animateTerminal(d);$('#pauseTerminal').onclick=e=>{terminalPaused=!terminalPaused;e.currentTarget.textContent=terminalPaused?'▶':'Ⅱ';e.currentTarget.setAttribute('aria-label',terminalPaused?'Resume terminal animation':'Pause terminal animation');};}}
async function copyText(text,button){try{await navigator.clipboard.writeText(text);const label=button.textContent;button.textContent='Copied!';setTimeout(()=>button.textContent=label,1800);}catch{toast('Select the text to copy it.');}}
const beforeExtra3=extraPage;
extraPage=function(r){if(['newsletter','digest'].includes(r))return `<section class="newsletter-hero"><div class="eyebrow">THE WEEKLY DIGEST</div><h1>This week in ${B.id==='lawyer'?'legal technology':'AI companies'}</h1><p>Useful components, new workflows and source-aware decisions.</p><form class="newsletter-form"><input type="email" aria-label="Email address" placeholder="your@email.com" required><button class="primary">Subscribe</button><small>Local preview · no email sent</small></form></section><section class="issue-list"><h2>All issues</h2>${[['Source-aware workflows','Research tools, licences and a repeatable review process.'],['Your connected stack','Skills, MCP servers and repositories in one workflow.'],['From component to company','Organize the capabilities behind your next project.']].map(([t,p],i)=>`<a href="#/article/${i}"><small>PREVIEW ISSUE / 0${i+1}</small><h2>${t}</h2><p>${p}</p><span>Read issue →</span></a>`).join('')}</section>`;
 if(r==='login')return `<section class="auth-page"><div class="auth-symbol">${ico('>_')}</div><h1>Sign in.</h1><p>Save resources and build your collection.</p><button id="demoLogin" class="primary">Continue in demo workspace</button><small>Local preview. No account credentials required.</small>${link('privacy','Privacy policy')}</section>`;
 if(r==='advertise')return `<section class="advertise-hero"><div class="eyebrow">SPONSORSHIPS</div><h1>Be there when builders<br>pick their next tool.</h1><p>Reach teams exploring ${B.id==='lawyer'?'legal technology':'AI company'} resources.</p>${link('contact','Discuss a placement →')}</section><h2>The Sponsorship</h2><div class="placement-grid">${[['Directory spotlight','Listing and category pages'],['Resource placement','Product, skill and MCP pages'],['Newsletter opening','The weekly resource digest']].map(([t,p])=>`<section><div class="placement-preview"><i></i><i></i><i></i></div><h2>${t}</h2><p>${p}</p><strong>Enquire for availability</strong>${link('contact','Prepare enquiry →')}</section>`).join('')}</div><section class="prose"><h2>How it works</h2><ol><li>Discuss the audience and placement.</li><li>Supply your product description and source evidence.</li><li>Review the placement before publication.</li></ol><p>No sponsorship contracts or live placements are offered by this prototype.</p></section>`;
 if(r==='sell')return `<section class="sell-hero"><div class="eyebrow">FOR CREATORS</div><h1>Turn your skills<br>into useful products.</h1><p>Prepare your own resource listing and storefront.</p><a class="primary" href="#/submit">Create a listing →</a></section><div class="steps-grid">${['Describe your skill','Attach source evidence','Prepare your listing','Review before publishing'].map((s,i)=>`<section><small>0${i+1}</small><h2>${s}</h2><p>Your draft stays in the local review queue.</p></section>`).join('')}</div>`;
 if(r==='hub')return `<section class="hub-hero"><div class="eyebrow">${B.name} HUB</div><h1>One home for your<br>skills and MCPs.</h1><p>Organize your resources, compare your options, and keep a source trail.</p><a class="primary" href="#/saved">Open your workspace →</a></section><div class="hub-console"><aside>WORKSPACE${[['saved','My components'],['review','Review queue'],['submit','Add resource']].map(r=>link(...r)).join('')}</aside><section><h2>Your component collection</h2>${D.filter(d=>state.saved.includes(d.id)).map(d=>`<div class="stack-row">${link('item/'+d.id,esc(d.name))}<span>${esc(d.type)}</span></div>`).join('')||'<p>Save resources from the directory to build your collection.</p>'}${link('discover','Browse resources →')}</section></div><div class="steps-grid">${['Discover','Compare','Collect','Review'].map(t=>`<section><h2>${t}</h2><p>Keep your workflow connected to the original source.</p></section>`).join('')}</div>`;
 if(r==='jobs')return `<section class="page-title"><div class="eyebrow">OPPORTUNITIES</div><h1>Jobs</h1><p>Roles for people building ${B.id==='lawyer'?'legal technology':'AI companies'}.</p></section><div class="empty"><h2>No verified vacancies yet.</h2><p>The jobs directory is ready for employer submissions.</p>${link('submit','Prepare a vacancy submission →')}</div>`;
 if(['learn','blog','docs','harness','harness-engineering','loop-engineering','agent-skills','what-are-skills','how-to-install','configuration-examples'].includes(r)){const guides=[['Choose a component','Match the task to a skill, agent or connector.'],['Connect your tools','Review runtime, authentication and permissions.'],['Inspect the source','Read the repository and its licence evidence.'],['Build a repeatable workflow','Keep configuration and review records together.']];return `<section class="page-title"><div class="eyebrow">GUIDES & DOCUMENTATION</div><h1>${({'learn':'Learn to build your stack','blog':'Guides & field notes','docs':'Documentation','harness':'Agent Harnesses','harness-engineering':'Harness Engineering','loop-engineering':'Loop Engineering','agent-skills':'Agent Skills','what-are-skills':'What Are Agent Skills?','how-to-install':'How to Install Components','configuration-examples':'Configuration Examples'})[r]}</h1><p>Practical guidance for ${B.id==='lawyer'?'legal technology':'AI company'} workflows.</p></section><div class="guide-layout"><nav>${guides.map(([t],i)=>`<a href="#/guide/${i}">0${i+1} ${t}</a>`).join('')}</nav><article><h2>${guides[0][0]}</h2><p>A skill contains reusable instructions. An MCP server connects an agent to tools or data. A repository contains the source needed to inspect, configure or develop a component.</p><div class="guide-cards">${guides.map(([t,p],i)=>`<a href="#/guide/${i}"><small>GUIDE 0${i+1}</small><h2>${t}</h2><p>${p}</p><span>Read guide →</span></a>`).join('')}</div></article></div>`;}
 if(r==='official')return `<section class="page-title"><h1>Source publishers</h1><p>Original maintainers in this catalogue.</p></section><div class="link-grid">${[...new Set(pool().map(d=>d.owner))].map(owner=>`<a class="link-tile" href="#/publisher/${encodeURIComponent(owner)}"><h2>${esc(owner)}</h2><span>${pool().filter(d=>d.owner===owner).length} resources →</span></a>`).join('')}</div>`;
 if(r==='trending'||r==='leaderboard')return `<section class="page-title"><div class="eyebrow">RESOURCE INDEX</div><h1>${r==='trending'?'Explore the catalogue':'Resource index'}</h1><p>Source samples in directory order. No popularity or download counts are fabricated.</p></section><div class="ranked-list">${pool().map((d,i)=>`<a href="${href(d)}"><b>${String(i+1).padStart(2,'0')}</b><div><h2>${esc(d.name)}</h2><p>${esc(d.summary)}</p></div>${badge(d.type)}</a>`).join('')}</div>`;
 return beforeExtra3(r);};
function appendLandingSections(){if(!$('#cards'))return;const target=$('.catalogue')||$('.template-directory');if(!target||V===5)return;const sets=V===1?[['Skills','skills',pool().filter(d=>d.type==='Skill')],['MCP servers','mcp-servers',pool().filter(d=>d.type==='MCP Server')],['Repositories & marketplaces','repositories',pool().filter(d=>['Repository','Plugin'].includes(d.type))]]:V===3?[['Browse by category','categories',null],['Resource index','leaderboard',pool()],['Latest resources','discover',pool().slice().reverse()]]:V===4?[['Skills','skills',pool().filter(d=>d.type==='Skill')],['MCP servers','mcp-servers',pool().filter(d=>d.type==='MCP Server')]]:[];target.insertAdjacentHTML('afterend',sets.map(([t,r,ds])=>`<section class="landing-section"><div class="section-heading"><h2>${t}</h2>${link(r,'View all →')}</div>${ds?`<div class="cards">${ds.length?ds.slice(0,6).map(card).join(''):`<p>No source-reviewed ${t.toLowerCase()} yet. <button data-demo-mode>View fictional layout examples</button></p>`}</div>`:`<div class="category-tiles">${[...new Set(pool().map(d=>d.category))].map(c=>`<a href="#/category/${encodeURIComponent(c)}"><h3>${esc(c)}</h3><strong>${pool().filter(d=>d.category===c).length}</strong> resources</a>`).join('')}</div>`}</section>`).join(''));}
const beforeRender3=render;
render=function(){terminalCancel++;const [,r='discover',id]=location.hash.split('/');let custom=false;if(typeMap[r]&&!['skills','plugins'].includes(r)){const items=pool().filter(d=>typeMap[r].includes(d.type));$('#main').innerHTML=searchView(r,items,r.replaceAll('-',' '));wireSearch(items);custom=true;}else if(['search','publisher'].includes(r)){const items=r==='publisher'?D.filter(d=>d.owner===decodeURIComponent(id||'')):pool();$('#main').innerHTML=searchView(r,items,r==='publisher'?decodeURIComponent(id||''):'Search resources');wireSearch(items);custom=true;}else if(['guide','article'].includes(r)){const n=Math.min(3,Math.max(0,+id||0)),titles=['Choose a component','Connect your tools','Inspect the source','Build a repeatable workflow'];$('#main').innerHTML=`<div class="breadcrumb">${link('learn','Learn')} / ${titles[n]}</div><article class="guide-article"><small>RESOURCE GUIDE / 0${n+1}</small><h1>${titles[n]}</h1><p class="lead">A practical workflow for ${B.id==='lawyer'?'legal technology':'AI company'} teams.</p>${['Define the task','Review the evidence','Start with a controlled setup','Keep the source record'].map((t,i)=>`<section><h2>${i+1}. ${t}</h2><p>${['Write down the inputs, expected outputs, and the limits of the work before choosing a resource.','Open the original repository. Check the maintainer, licence and maintenance status. Match the component to your runtime.','Use a test environment and the minimum permissions needed. Review what data leaves your environment.','Save the resource and record the source version, configuration and decisions for the next review.'][i]}</p></section>`).join('')}<a class="primary" href="#/discover">Explore components →</a></article>`;custom=true;}else if(advancedRoutes.includes(r)){if(['feedback','ranking-methodology'].includes(r)){if(r==='feedback'){location.replace('#/contact');return;}$('#main').innerHTML=infoPage('how-listings-work');}else $('#main').innerHTML=extraPage(r);custom=true;}else beforeRender3();if(custom){document.title=B.name+' — '+r;paintCompare();}if(r==='discover')appendLandingSections();document.body.dataset.page=r;$('#mode').value=state.mode;if($('#savedCount'))$('#savedCount').textContent=state.saved.length||'';$$('.template-sidebar a').forEach(a=>a.classList.toggle('active',a.hash==='#/'+r));wireCards();wireResource(D.find(d=>d.id===id));$$('[data-demo-mode]').forEach(b=>b.onclick=()=>{state.mode='demo';render();});$$('.newsletter-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();toast('Subscription preview complete. No email was sent.');});$('#demoLogin')&&($('#demoLogin').onclick=()=>location.hash='/hub');document.body.classList.remove('side-mobile-open');};
